mapper.select:
select sku.id as sku_id, item.id as item_id, item.item_code, item.item_name, sku.sku_code, sku.sku_name, item.unit, sku.cost_price, ifnull(stock.stock_qty, 0) as stock_quantity, ifnull(outflow.out_qty, 0) as out_quantity, ifnull(inflow.in_qty, 0) as in_quantity from wms_item_sku sku inner join wms_item item on sku.item_id = item.id left join ( select sku_id, sum(quantity) as stock_qty from wms_inventory
warehouse_id = #{warehouseId}
group by sku_id ) stock on stock.sku_id = sku.id left join ( select sku_id, sum(abs(quantity)) as out_qty from wms_inventory_history where order_type = 2
and create_time >= #{startTime}
and create_time <= #{endTime}
and warehouse_id = #{warehouseId}
group by sku_id ) outflow on outflow.sku_id = sku.id left join ( select sku_id, sum(quantity) as in_qty from wms_inventory_history where order_type = 1
and create_time >= #{startTime}
and create_time <= #{endTime}
and warehouse_id = #{warehouseId}
group by sku_id ) inflow on inflow.sku_id = sku.id
item.item_name like concat('%', #{itemName}, '%')
and ( ifnull(inflow.in_qty, 0) > 0 or ifnull(outflow.out_qty, 0) > 0 or ifnull(stock.stock_qty, 0) > 0 )
order by ifnull(outflow.out_qty, 0) desc, sku.id

select sku.id as sku_id, item.id as item_id, item.item_code, item.item_name, sku.sku_code, sku.sku_name, item.unit, sku.cost_price, ifnull(stock.stock_qty, 0) as end_quantity, ifnull(inflow.in_qty, 0) as in_quantity, ifnull(outflow.out_qty, 0) as out_quantity, ifnull(checkadj.check_qty, 0) as check_quantity, ifnull(stock.stock_qty, 0) - ifnull(inflow.in_qty, 0) + ifnull(outflow.out_qty, 0) - ifnull(checkadj.check_qty, 0) as begin_quantity from wms_item_sku sku inner join wms_item item on sku.item_id = item.id left join ( select sku_id, sum(quantity) as stock_qty from wms_inventory
warehouse_id = #{warehouseId}
group by sku_id ) stock on stock.sku_id = sku.id left join ( select sku_id, sum(quantity) as in_qty from wms_inventory_history where order_type = 1
and create_time >= #{startTime}
and create_time <= #{endTime}
and warehouse_id = #{warehouseId}
group by sku_id ) inflow on inflow.sku_id = sku.id left join ( select sku_id, sum(abs(quantity)) as out_qty from wms_inventory_history where order_type = 2
and create_time >= #{startTime}
and create_time <= #{endTime}
and warehouse_id = #{warehouseId}
group by sku_id ) outflow on outflow.sku_id = sku.id left join ( select sku_id, sum(quantity) as check_qty from wms_inventory_history where order_type = 4
and create_time >= #{startTime}
and create_time <= #{endTime}
and warehouse_id = #{warehouseId}
group by sku_id ) checkadj on checkadj.sku_id = sku.id
item.item_name like concat('%', #{itemName}, '%')
and ( ifnull(inflow.in_qty, 0) > 0 or ifnull(outflow.out_qty, 0) > 0 or ifnull(stock.stock_qty, 0) > 0 )
order by ifnull(outflow.out_qty, 0) desc, sku.id

select date_format(h.create_time, '%Y-%m') as month, ifnull(sum(case when h.order_type = 1 then h.quantity else 0 end), 0) as in_quantity, ifnull(sum(case when h.order_type = 2 then abs(h.quantity) else 0 end), 0) as out_quantity, round(ifnull(sum(case when h.order_type = 1 then h.quantity * sku.cost_price else 0 end), 0), 2) as in_amount, round(ifnull(sum(case when h.order_type = 2 then abs(h.quantity) * sku.cost_price else 0 end), 0), 2) as out_amount from wms_inventory_history h left join wms_item_sku sku on h.sku_id = sku.id
h.order_type in (1, 2)
and h.warehouse_id = #{warehouseId}
and h.create_time >= #{startTime}
and h.create_time <= #{endTime}
group by date_format(h.create_time, '%Y-%m') order by month

select co.id as check_order_id, co.order_no, co.order_status, co.create_time, d.id as detail_id, sku.id as sku_id, item.id as item_id, item.item_code, item.item_name, sku.sku_code, sku.sku_name, item.unit, sku.cost_price, d.warehouse_id, w.warehouse_name, z.zone_name, l.location_code, d.quantity, d.check_quantity, (d.check_quantity - d.quantity) as diff_quantity from wms_check_order_detail d inner join wms_check_order co on d.order_id = co.id inner join wms_item_sku sku on d.sku_id = sku.id inner join wms_item item on sku.item_id = item.id left join wms_warehouse w on d.warehouse_id = w.id left join wms_zone z on d.zone_id = z.id left join wms_location l on d.location_id = l.id
d.check_quantity is not null and d.check_quantity != d.quantity
and d.warehouse_id = #{warehouseId}
and item.item_name like concat('%', #{itemName}, '%')
and co.create_time >= #{startTime}
and co.create_time <= #{endTime}
order by co.create_time desc, d.id
